function ensureAudio(){ if(!actx){ actx=new (window.AudioContext||window.webkitAudioContext)(); } if(actx.state==='suspended') actx.resume(); }
function beep(freq,dur,type,vol,delay){
  if(!actx) return;
  const t0=actx.currentTime+(delay||0);
  const osc=actx.createOscillator(), gain=actx.createGain();
  osc.type=type||'sine'; osc.frequency.setValueAtTime(freq,t0);
  gain.gain.setValueAtTime(vol||0.2,t0); gain.gain.exponentialRampToValueAtTime(0.001,t0+dur);
  osc.connect(gain); gain.connect(actx.destination);
  osc.start(t0); osc.stop(t0+dur+0.03);
}
function sfxClick(){ beep(700,0.06,'sine',0.15); }
function sfxHit(){ beep(180,0.12,'square',0.25); beep(90,0.18,'square',0.2,0.05); }
function sfxKO(){ beep(70,0.4,'sawtooth',0.3); beep(50,0.5,'square',0.25,0.1); }
function sfxLevelUp(){ beep(523,0.15,'sine',0.2); beep(659,0.15,'sine',0.2,0.15); beep(784,0.3,'sine',0.25,0.3); }
function noise(dur,vol,freq,delay){
  if(!actx) return;
  const t0=actx.currentTime+(delay||0), n=Math.floor(actx.sampleRate*dur), buf=actx.createBuffer(1,n,actx.sampleRate), d=buf.getChannelData(0);
  for(let i=0;i<n;i++) d[i]=Math.random()*2-1;
  const src=actx.createBufferSource(); src.buffer=buf;
  const f=actx.createBiquadFilter(); f.type='bandpass'; f.frequency.value=freq||1500;
  const g=actx.createGain(); g.gain.setValueAtTime(vol,t0); g.gain.exponentialRampToValueAtTime(0.001,t0+dur);
  src.connect(f); f.connect(g); g.connect(actx.destination); src.start(t0);
}
function sweep(f0,f1,dur,type,vol,delay){
  if(!actx) return;
  const t0=actx.currentTime+(delay||0), o=actx.createOscillator(), g=actx.createGain();
  o.type=type||'sawtooth'; o.frequency.setValueAtTime(f0,t0); o.frequency.exponentialRampToValueAtTime(f1,t0+dur);
  g.gain.setValueAtTime(vol||0.12,t0); g.gain.exponentialRampToValueAtTime(0.001,t0+dur);
  o.connect(g); g.connect(actx.destination); o.start(t0); o.stop(t0+dur+0.03);
}
