function kp(name){ if(!latestKP) return null; const k=latestKP.find(p=>p.name===name); return (k&&k.score>0.25)?k:null; }
let shrugPct=0;
function neckRatio(){
  const ls=kp('left_shoulder'),rs=kp('right_shoulder'),s=shoulderScale(); if(!ls||!rs||!s) return null;
  let hy=null; const n=kp('nose');
  if(n) hy=n.y; else { const a=kp('left_eye'),b=kp('right_eye'); if(a&&b) hy=(a.y+b.y)/2; }
  return hy===null?null:((ls.y+rs.y)/2-hy)/s;
}
function shoulderScale(){ const ls=kp('left_shoulder'),rs=kp('right_shoulder'); return (ls&&rs)? Math.hypot(ls.x-rs.x,ls.y-rs.y) : null; }

