async function initCamera(){
  const stream=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:1280},height:{ideal:720},facingMode:'user'}});
  vid.srcObject=stream;
  await new Promise(r=>vid.onloadedmetadata=r);
  vid.play();
}
async function initDetector(){
  await tf.setBackend('webgl'); await tf.ready();
  detector=await poseDetection.createDetector(poseDetection.SupportedModels.MoveNet,{modelType:poseDetection.movenet.modelType.SINGLEPOSE_LIGHTNING});
}
async function detectLoop(){
  if(detector&&vid.readyState>=2){
    try{const poses=await detector.estimatePoses(vid); if(poses[0]) latestKP=poses[0].keypoints;}catch(e){}
  }
  drawSkeleton();
  if(tabNow==='detect') updateDetectPanel();
  requestAnimationFrame(detectLoop);
}
function drawSkeleton(){
  const ctx=skel.getContext('2d');
  ctx.save(); ctx.clearRect(0,0,W,H);
  ctx.translate(W,0); ctx.scale(-1,1);
  const vw=vid.videoWidth||W, vh=vid.videoHeight||H;
  const sc=Math.min(W/vw,H/vh), cv=Math.max(W/vw,H/vh), ox=(W-vw*sc)/2, oy=(H-vh*sc)/2;
  if(vid.readyState>=2){
    ctx.save(); try{ ctx.filter='blur(12px) brightness(0.55)'; }catch(e){}
    ctx.drawImage(vid,(W-vw*cv)/2,(H-vh*cv)/2,vw*cv,vh*cv); ctx.restore();
    ctx.drawImage(vid,ox,oy,vw*sc,vh*sc);
  }
  ctx.translate(ox,oy); ctx.scale(sc,sc);
  if(latestKP) drawHeroOverlay(ctx,sc);
  ctx.restore();
}

