    const p=ph+k*Math.PI, a=air?(k?1.0:-0.35):(mv?Math.sin(p)*0.75:(k?-0.08:0.08)), b=air?a-1.0:a-(mv?0.7*Math.max(0,Math.cos(p)):0);
