  let vx=0;
  if(!encountering){
    if(dashT>0){ dashT-=delta; vx=heroFace*520; trail.push({x:heroX,y:heroY,l:1}); }
    else if(hurtT>800){ vx=kvx; }
    else if(moveDir){ vx=moveDir*170; heroFace=moveDir; }
  }
  heroX=Math.max(24,Math.min(worldW-24,heroX+vx*dt));
  const lim=defeated.indexOf(false); if(lim>=0) heroX=Math.min(heroX,monsterX[lim]-55*SZ);
