    exploreG.fillStyle(0x38bdf8,0.22+0.1*Math.sin(time*0.006+i)); exploreG.fillCircle(gx,gyy,14);
    exploreG.fillStyle(0x38bdf8,1); exploreG.beginPath(); exploreG.moveTo(gx,gyy-9); exploreG.lineTo(gx+6.5,gyy); exploreG.lineTo(gx,gyy+9); exploreG.lineTo(gx-6.5,gyy); exploreG.closePath(); exploreG.fillPath();
    exploreG.lineStyle(1.5,0x0f172a,1); exploreG.strokePath();
