let toastQ=[], toastBusy=false;
function toast(m){ toastQ.push(m); if(!toastBusy) nextToast(); }
function nextToast(){
  const el=document.getElementById('toast'), m=toastQ.shift();
  if(!m){ toastBusy=false; el.style.display='none'; return; }
  toastBusy=true; el.textContent=m; el.style.display='block'; setTimeout(nextToast,1600);
}
