function markDay(){
  const ld=d=>d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate();
  const today=ld(new Date()), y=ld(new Date(Date.now()-864e5));
  if(userData.lastDay===today) return;
  userData.streak=(userData.lastDay===y)?userData.streak+1:1; userData.lastDay=today;
}
