function setGauge(id,pct,col){ const e=document.getElementById(id); e.style.width=Math.max(0,Math.min(100,pct))+'%'; e.style.background=col; }
const gcol=(v,a,b)=>v<a?'#4ade80':(v<b?'#fbbf24':'#ef4444');
function updateDetectPanel(){
  document.getElementById('skel2').getContext('2d').drawImage(skel,0,0);
  const msg=document.getElementById('camMsg');
  if(!camStarted){ msg.textContent='ยังไม่ได้เปิดกล้อง กดปุ่ม "เปิดกล้อง" ด้านล่าง'; return; }
  const ls=kp('left_shoulder'),rs=kp('right_shoulder');
  if(!ls||!rs){ msg.textContent='มองไม่เห็นไหล่ทั้งสองข้าง ลองขยับให้อยู่ในกล้อง'; return; }
  msg.textContent='';
  const ang=(a,b)=>{ let d=Math.atan2(b.y-a.y,b.x-a.x)*180/Math.PI; if(d>90) d-=180; if(d<-90) d+=180; return Math.abs(d); };
  const sh=ang(ls,rs);
  const le=kp('left_ear'),re=kp('right_ear'), lee=kp('left_eye'), ree=kp('right_eye');
  const hd=(le&&re)?ang(le,re):((lee&&ree)?ang(lee,ree):null);
  const r=neckRatio(); let nk=null;
  if(calNeck!==null&&r!==null) nk=Math.max(0,(calNeck-r)/calNeck*100);
  document.getElementById('vSh').textContent=sh.toFixed(1);
  document.getElementById('vHd').textContent=hd===null?'--':hd.toFixed(1);
  document.getElementById('vNk').textContent=nk===null?(calNeck===null?'กดตั้งค่าท่านั่งตรงก่อน':'--'):nk.toFixed(0)+'%';
  setGauge('gSh',sh*10,gcol(sh,3,6)); setGauge('gHd',(hd||0)*8,gcol(hd||0,4,8)); setGauge('gNk',(nk||0)*5,gcol(nk||0,6,12));
  let score=100-Math.min(40,sh*6)-Math.min(30,(hd||0)*4)-(nk===null?0:Math.min(30,nk*2));
  score=Math.round(Math.max(0,score));
  document.getElementById('postScore').textContent=score;
  document.getElementById('postLabel').textContent=score>=80?'ดีมาก 👍':(score>=60?'พอใช้':'ควรปรับท่า ⚠️');
  setGauge('gScore',score,score>=80?'#4ade80':(score>=60?'#fbbf24':'#ef4444'));
}
