document.getElementById('camBtn').onclick=async()=>{
  ensureAudio(); const m=document.getElementById('camMsg'); m.textContent='กำลังเปิดกล้อง...';
  try{ await startCameraOnly(); }catch(e){ m.textContent='เปิดกล้องไม่สำเร็จ กรุณาอนุญาตการใช้กล้อง'; }
};
document.getElementById('calBtn').onclick=async()=>{
  const msg=document.getElementById('camMsg');
  const btn=document.getElementById('calBtn');
  const oldText=btn.textContent;
  btn.disabled=true;
  try{
    if(!camStarted){ msg.textContent='กำลังเปิดกล้องเพื่อวัดท่านั่งปกติ...'; await startCameraOnly(); }
    msg.textContent='นั่งหลังตรง มองตรง และผ่อนคลายไหล่ กำลังตรวจจับ...';
    let r=null;
    const until=Date.now()+6000;
    while(Date.now()<until){
      r=neckRatio();
      const ls=kp('left_shoulder'),rs=kp('right_shoulder'),nose=kp('nose');
      if(r!==null&&ls&&rs&&nose) break;
      await new Promise(resolve=>setTimeout(resolve,150));
    }
    if(r===null||!kp('left_shoulder')||!kp('right_shoulder')){
      msg.textContent='ยังจับใบหน้าและไหล่ไม่ครบ กรุณานั่งให้เห็นไหล่ทั้งสองข้าง มีแสงสว่าง แล้วกดตั้งค่าอีกครั้ง';
      toast('ตั้งค่าท่านั่งไม่สำเร็จ');
      return;
    }
    calNeck=r; baselineNeck=r;
    msg.textContent='บันทึกท่านั่งตรงแล้ว ✓ ใช้ท่านี้เป็นค่าอ้างอิง';
    btn.textContent='✓ บันทึกท่านั่งตรงแล้ว';
    btn.classList.add('sel');
    updateDetectPanel();
    toast('บันทึกท่านั่งตรงแล้ว');
    showStartPop(true);
  }catch(e){
    msg.textContent='เปิดกล้องไม่สำเร็จ กรุณาอนุญาตการใช้กล้องแล้วลองใหม่';
    toast('เปิดกล้องไม่สำเร็จ');
  }finally{ btn.disabled=false; if(!calNeck) btn.textContent=oldText; }
};
const BREAK=[
 {n:'เงยหน้า',d:'นั่งหลังตรง มองตรงก่อน แล้วค่อยๆ เงยหน้าขึ้นเล็กน้อย มองเฉียงขึ้นโดยไม่แอ่นคอมากเกินไป ค้างไว้ หายใจช้าๆ'},
 {n:'เอียงคอยืดบ่าซ้าย',d:'เอียงหูซ้ายเข้าหาไหล่ซ้ายเบาๆ ไหล่ขวาลดต่ำ ไม่ต้องเกร็งหรือดึง'},
 {n:'เอียงคอยืดบ่าขวา',d:'เอียงหูขวาเข้าหาไหล่ขวาเบาๆ ไหล่ซ้ายลดต่ำ หายใจเข้าออกช้าๆ'},
 {n:'ยักไหล่ขึ้น-ลง',d:'ยักไหล่ขึ้นใกล้หู ค้าง 3 วินาที แล้วปล่อยลงช้าๆ ทำซ้ำ'},
 {n:'เปิดอกท่า W',d:'ยกศอกงอ 90° มือชี้ขึ้น บีบสะบักเข้าหากัน เปิดอกค้างไว้'},
 {n:'ยกแขนยืดตัว (Y)',d:'ยกแขนเหนือศีรษะเป็นรูปตัว Y ยืดตัวขึ้นช้าๆ หายใจลึกๆ'}
];
let brkIdx=-1, brkLeft=30, brkRun=false, brkTimer=null;
function brkRender(){
  document.getElementById('brkList').innerHTML=BREAK.map((b,i)=>'<li style="'+(i===brkIdx?'color:#fde047;font-weight:700':(i<brkIdx?'opacity:.5':''))+'">'+b.n+'</li>').join('');
  const total=Math.max(0,(BREAK.length-Math.max(brkIdx,0))*30-(brkIdx<0?0:30-brkLeft));
  const left=brkIdx<0?180:Math.max(0,(BREAK.length-brkIdx-1)*30+brkLeft);
  const m=Math.floor(left/60), s=Math.ceil(left%60);
  document.getElementById('brkTime').textContent=(brkIdx<0?'3:00':(m+':'+String(s===60?0:s).padStart(2,'0')));
  document.getElementById('brkBar').style.width=(brkIdx<0?0:100*(1-left/180))+'%';
}
function brkNext(){
  brkIdx++; brkLeft=30; beep(660,0.12,'sine',0.2); beep(880,0.15,'sine',0.2,0.12);
  if(brkIdx>=BREAK.length){
    clearInterval(brkTimer); brkRun=false; brkIdx=-1;
    document.getElementById('brkName').textContent='เสร็จแล้ว! เยี่ยมมาก 🎉';
    document.getElementById('brkDesc').textContent='ครบโปรแกรม 3 นาที ผ่อนคลายคอ บ่า ไหล่แล้ว';
    userData.stats.breaks++; userData.stats.seconds+=180; markDay(); toast('บริหารครบ 3 นาที! +60 XP  +15 🪙'); addCoins(15); addXP(60); sfxVictory();
    document.getElementById('brkTime').textContent='0:00'; document.getElementById('brkBar').style.width='100%';
    return;
  }
  document.getElementById('brkName').textContent='ท่าที่ '+(brkIdx+1)+'/'+BREAK.length+': '+BREAK[brkIdx].n;
  document.getElementById('brkDesc').textContent=BREAK[brkIdx].d;
  brkRender();
}
document.getElementById('brkStart').onclick=()=>{
  ensureAudio(); clearInterval(brkTimer); brkIdx=-1; brkRun=true; document.getElementById('brkPause').textContent='พัก'; brkNext();
  brkTimer=setInterval(()=>{ if(!brkRun) return; brkLeft-=0.25; if(brkLeft<=0) brkNext(); else brkRender(); },250);
};
document.getElementById('brkPause').onclick=()=>{ if(brkIdx<0) return; brkRun=!brkRun; document.getElementById('brkPause').textContent=brkRun?'พัก':'ทำต่อ'; };
document.getElementById('brkSkip').onclick=()=>{ if(brkIdx>=0) brkNext(); };
brkRender(); refreshTop(); checkBadges();
tabNow='home';
function pctLine(i){
  const v=i===2?shrugPct:(i===4?tuckState.pct:undefined);
  if(v===undefined) return '';
  return v===null?'\n(มองไม่เห็นจุดที่ต้องใช้ ลองขยับให้อยู่ในกล้อง)':'\n('+(i===2?'ยกไหล่':'เงยหน้า')+'ได้ '+v+'%)';
}

function setHold(h){
  NEED=h*1000;
  document.querySelectorAll('[data-h]').forEach(x=>x.classList.toggle('sel',+x.dataset.h===h));
  document.getElementById('lvlInfo').textContent='ค้างท่าละ '+h+' วินาที ท่าละ 1 ครั้ง';
}
document.querySelectorAll('[data-h]').forEach(b=>b.onclick=()=>setHold(+b.dataset.h));
function showStartPop(anim){
  const pop=document.getElementById('startPop'); pop.style.display='block';
  if(anim){ pop.classList.remove('pop'); void pop.offsetWidth; pop.classList.add('pop'); sfxCoin(); setTimeout(()=>pop.scrollIntoView({behavior:'smooth',block:'center'}),80); }
}
